			// [Function] 신청자 데이터 요청, 저장 프로세스 영역 - 입소관리, 입소접수 공통
			//================================================================================= 
			/**
			 * 상세 데이터 조회
			 * @param psStatus - 조회 상태(저장 후 조회인 경우에는 'save' 구분값 넘김)
			 */
			function doDtl(psStatus) {
			    
			    //상세 조회 서브미션 호출
			    util.Submit.send(app, "subDtl", function(pbSuccess) {
			        if (pbSuccess) {
			            stateLclas = util.DataMap.getValue(app, "dmAplCntDtl", "APLY_RCPT_SRNG_SE_CD"); // 대분류 진행 상태
			            stateSclas = util.DataMap.getValue(app, "dmAplCntDtl", "APLY_RCPT_SRNG_PRGRS_STTS_SE_CD"); // 소분류 진행 상태
			            papersSbmsnSeCd = util.DataMap.getValue(app, "dmAplCntDtl", "PAPERS_SBMSN_SE_CD"); // 서류제출구분코드 
			            rqstPicYn = util.DataMap.getValue(app, "dmAplCntDtl", "RQST_PIC_YN"); // 의뢰관리자여부
			            
			            if(util.DataMap.getValue(app,"dmAplCntDtl", "RCPT_RQST_COURS_SE_CD") == '99999999')
			                util.DataMap.setValue(app, "dmAplCntDtl", "RCPT_RQST_COURS_SE_NM", '기타')
			            grpRcptRqstCoursVisible();
			            
			            // ### 대상자용 ###
			            
			            // 신청자, 대상자 공용으로 insert, update 구분 사용
			            app.lookup("dmDetail").setValue("TYPE", "u");
			            
			            // 가족정보
			            util.Submit.send(app, "subFamInfo", function(pbSuccess) {});
			            // 학력상태
			            util.Submit.send(app, "subAcbgStts", function(pbSuccess) {});
			            // 중단상태
			            util.Submit.send(app, "subSchulwDscntc", function(pbSuccess) {});
			            // 심사점수
			            util.Submit.send(app, "subTest", function(pbSuccess) {
			                
			                var Qustnb = app.lookup("dsQustnb").getValue(0, "SUMQ");
			                var Qustnb2 = app.lookup("dsQustnb2").getValue(0, "SUMQ");
			                var Qustnb3 = app.lookup("dsQustnb3").getValue(0, "SUMQ");
			                
			//                console.log("fewfwfqqwer : " + Qustnb + " +++ and +++ " + Qustnb2 + "--- and --- " + Qustnb3);
			                
			                // 임시(사전설문지 자가진단 결과가 없을경우 0점)처리
			                if (ValueUtil.isNull(Qustnb))
			                    Qustnb = '0';
			                if (ValueUtil.isNull(Qustnb2))
			                    Qustnb2 = '0';
			                if (ValueUtil.isNull(Qustnb3))
			                    Qustnb3 = '0';
			                
			                app.lookup("opt55").text = "청소년 인터넷 과의존 자가진단 척도(K척도) " + Qustnb + "점 \n" +
			                    "청소년 스마트폰 과의존 자가진단 척도(S-척도) " + Qustnb2 + "점 \n" +
			                    "청소년 인터넷 과의존 관찰자 척도(K-척도) " + Qustnb3 + "점"
			                
			            });
			            if (psStatus == "save") {
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            } else {
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			            
			            formRowVisible_fn("grp_TRPR_REL_SE_CD", "cmb_TRPR_REL_SE_CD", "ipb_TRPR_REL_SE_CD");
			            formRowVisible_fn("grp_RESIDE_SHAPE_SE_CD", "cmb_RESIDE_SHAPE_SE_CD", "ipb_RESIDE_SHAPE_SE_CD");
			            formRowVisible_fn("grp_FAM_SHAPE_SE_CD", "cmb_FAM_SHAPE_SE_CD", "ipb_FAM_SHAPE_SE_CD");
			            
			            // 사례이력있을시 경고문구 노출
			            if(app.lookup("dmAplCntDtl").getValue("CASE_HSTR_CNT") > 0)
			                util.Control.setVisible(app, true, "cominfomsg1");
			            else
			                util.Control.setVisible(app, false, "cominfomsg1");
			            
			            // 신청자 초기 화면 구성
			            initCrud();
			        }
			    });
			}

