			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e) {
			    
			    /*##############유효성검사(신청정보)##############*/
			    if (!util.validate(app, "grp3")) return false;
			    
			    /*##############유효성검사(의뢰담당자 여부 내 프리폼)#################*/
			    if (rqstPicYn == "Y") {
			        // 프리폼 내 컬럼 유효성 체크
			        if (!util.validate(app, "grp10")) return false;
			    }
			    
			    // 의뢰담당자, 대상자, 보호자 설문 수신 방법 체크
			    if (!validateSrvyRcptnMthd()) return;
			    
			    /*##############유효성검사(생년월일 현재일 이후 입력 여부)###############*/
			    var sTrprBrthYmd = app.lookup("dmDetail").getValue("TRPR_BRTH_YMD");
			    if (sTrprBrthYmd > vsToday) {
			        util.Msg.alert(app, "생년월일이 현재일 이후로 입력되었습니다.\n생년월일을 확인/수정 바랍니다.", null, function() {
			            util.Control.setFocus(app, "cmn_TRPR_BRTH_YMD");
			        }, "생년월일");
			    }
			    if (!util.validate(app, "cmn_TRPR_BRTH_YMD")) return false; // 생년월일
			    
			    // ### 대상자, 보호자 유효성 체크 ###############################################################
			    // 프리폼 내 컬럼 유효성 체크
			    if (!util.validate(app, "grpPrvcSub")) return false;
			    
			    // 2022-07-21 YOO.CHI.HOON
			    // ###################주민번호 및 개인식별번호 다시한번 체크############################
			    if (!rrnoValidationChk()) return false;
			    
			    // ###################입교신청 가능 여부체크 ############################
			    entscAplyPsbltyYnChk();
			    
			    if (isEntscAplyPsbltyYn == false) {
			        return false;
			    }
			    
			    if (!util.validate(app, "grpPrtcrSub")) return false;
			    
			    //######################## 가족정보탭 유효성 체크######################
			    if (!util.validate(app, "grdFamInfo", "필수체크")) return false; // 사례대상자가족
			    
			    //########################학력상태탭 유효성 체크#######################    
			    if (!util.validate(app, "grdAcbgStts", "필수체크")) return false; // 학력상태
			    
			    var grdAcbgSttsRowIndex = util.Grid.getIndex(app, "grdAcbgStts");
			    var sMtcltnYmd = util.Grid.getCellValue(app, "grdAcbgStts", "MTCLTN_YMD", grdAcbgSttsRowIndex); /* 입학일자*/
			    var sGrdtnYmd = util.Grid.getCellValue(app, "grdAcbgStts", "GRDTN_YMD", grdAcbgSttsRowIndex); /* 졸업일자*/
			    
			    var isMtcltnYmd = Number(sMtcltnYmd);
			    var isGrdtnYmd = Number(sGrdtnYmd);
			    
			    if (isMtcltnYmd != 0 && isGrdtnYmd > 0) {
			        if (isMtcltnYmd >= isGrdtnYmd) {
			            var psTitle = "졸업일자";
			            var psMsgId = "졸업일자가 입학일자 이전으로 입력되었습니다.\n졸업일자를 확인 후 다시 입력 바랍니다.";
			            util.Msg.alert(app, psMsgId, null, function() {}, psTitle);
			            return false;
			        }
			    }
			    if (isGrdtnYmd != 0 && isMtcltnYmd > 0) {
			        if (isGrdtnYmd <= isMtcltnYmd) {
			            var psTitle = "입학일자";
			            var psMsgId = "입학일자가 졸업일자 이후로 입력되었습니다.\n졸업일자를 확인 후 다시 입력 바랍니다.";
			            util.Msg.alert(app, psMsgId, null, function() {}, psTitle);
			            return false;
			        }
			    }
			    
			    if (!util.validate(app, "grdSchulwDscntc", "필수체크")) return false; // 중단상태
			    
			    // 2022-10-11 YOO.CHI.HOON 단위테스트 결함사항으로 인한 추가
			    // ##################주민번호와 선택한 성별간 일치, 생일 일치 여부#######################
			    var sRrno = app.lookup("dmDetail").getValue("RRNO"); /* 주민등록번호*/
			    var sTrprBrthYmd = app.lookup("dmDetail").getValue("TRPR_BRTH_YMD"); /* 대상자생년월일*/
			    var sSxdcSeCd = app.lookup("dmDetail").getValue("SXDC_SE_CD"); /* 대상자성별*/
			    if (!ValueUtil.isNull(sRrno) || sRrno != "") {
			        
			        // 성별
			        var chkRrnoSxdc = "";
			        chkRrnoSxdc = rrnoSxdcChk(sRrno);
			        if (sRrno != null) {
			            if (sSxdcSeCd != chkRrnoSxdc) {
			                var psMsgId = "대상자의 선택한 성별(" + (sSxdcSeCd == "M" ? "남자" : "여자") + ")과 주민등록 번호의 성별(" + (chkRrnoSxdc == "M" ? "남자" : "여자") + ")이 상이합니다. 확인 후 재입력 바랍니다.\n ";
			                util.Msg.alert(app, psMsgId, null, function() {
			                    util.Control.setFocus(app, "rdb_SXDC_SE_CD");
			                }, "주민등록번호 성별");
			                return false;
			            }
			            
			            // 생년월일
			            var chkRrnoBrthYmd = "";
			            chkRrnoBrthYmd = rrnoBrdtChk(sRrno);
			            
			            if (sTrprBrthYmd != chkRrnoBrthYmd) {
			                var psMsgId = "대상자의 입력한 생년월일과(" + (sTrprBrthYmd) + ")과 주민등록 번호의 생년월일이(" + (chkRrnoBrthYmd) + ")이 상이합니다. 확인 후 재입력 바랍니다.";
			                util.Msg.alert(app, psMsgId, null, function() {
			                    util.Control.setFocus(app, "rdb_SXDC_SE_CD");
			                }, "주민등록번호 성별");
			                return false;
			            }
			        }
			    }
			    
			    // 프리폼 내 컬럼 유효성 체크
			    if (!util.validate(app, "grpPrtcrSub")) return false;
			    
			    // ### 서류점검 폼 유효성 체크 ###############################################################
			    if (stateSclas == "0102") {
			        // 설문지점수 그룹 폼 활성화 여부
			        if (ValueUtil.isNull(app.lookup("rdb5").value)) {
			            util.Msg.alert(app, "서류점검 폼에 서류제출여부 선택 및 \n보완서류내용을 입력 해주세요.");
			            return false;
			        } else if (app.lookup("rdb5").value == "0") {
			            if (ValueUtil.isNull(app.lookup("ipb18").value)) {
			                util.Msg.alert(app, "서류 제출 여부를 아니요로 선택 하셨습니다.  \n보완서류내용을 입력 해주세요.");
			                return false;
			            }
			        }
			    }
			    
			    var psMsgId = "저장하시겠습니까?";
			    util.Msg.confirm(app, psMsgId, null, function() {
			        doSave(); // 상세저장
			    }, function() {
			        return false;
			    }, "저장확인");
			}

